package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.PedidoPecasResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class PedidoPecasRepository extends JdbcSupport implements Repository<PedidoPecas,Long>{private static final PedidoPecasRepository INSTANCE=new PedidoPecasRepository();public static PedidoPecasRepository getInstance(){return INSTANCE;}public PedidoPecas cadastrar(PedidoPecas x){return save(x);}public List<PedidoPecas>listarTodos(){return findAll();}public PedidoPecas buscarPorNumero(Long n){return findById(n).orElse(null);}public List<PedidoPecas>buscarPorOrdemServicoId(Long id){return query("SELECT * FROM pedidos_pecas WHERE numero_os=?",new PedidoPecasResultSetMapper()::map,id);}public List<PedidoPecas>buscarPorStatus(StatusPedidoPecas s){return query("SELECT * FROM pedidos_pecas WHERE status=?",new PedidoPecasResultSetMapper()::map,s.name());}public PedidoPecas atualizar(Long id,PedidoPecas x){x.setNumeroPedido(id);return update(x);}public PedidoPecas atualizarStatus(Long id,StatusPedidoPecas s){PedidoPecas x=buscarPorNumero(id);if(x==null)return null;x.setStatus(s);if(s==StatusPedidoPecas.ENTREGUE)x.marcarEntregue();return update(x);}public PedidoPecas registrarPagamento(Long id,double valor){PedidoPecas x=buscarPorNumero(id);if(x==null)return null;x.registrarPagamento(valor);return update(x);}public PedidoPecas deletar(Long id){PedidoPecas x=buscarPorNumero(id);if(x!=null)deleteById(id);return x;}public int getTotalPedidos(){return findAll().size();}public void limpar(){execute("DELETE FROM pedidos_pecas");}
 public PedidoPecas save(PedidoPecas x){long id=insert("INSERT INTO pedidos_pecas(numero_os,status,fornecedor,valor_total,valor_pago,observacoes) VALUES(?,?,?,?,?,?)",x.getOrdemServico().getNumeroOS(),x.getStatus().name(),x.getFornecedor(),x.getValorTotal(),x.getValorPago(),x.getObservacoes());x.setNumeroPedido(id);return x;}public Optional<PedidoPecas>findById(Long id){return query("SELECT * FROM pedidos_pecas WHERE numero_pedido=?",new PedidoPecasResultSetMapper()::map,id).stream().findFirst();}public List<PedidoPecas>findAll(){return query("SELECT * FROM pedidos_pecas ORDER BY numero_pedido",new PedidoPecasResultSetMapper()::map);}public PedidoPecas update(PedidoPecas x){int n=execute("UPDATE pedidos_pecas SET numero_os=?,status=?,fornecedor=?,valor_total=?,valor_pago=?,observacoes=?,data_atualizacao=CURRENT_TIMESTAMP WHERE numero_pedido=?",x.getOrdemServico().getNumeroOS(),x.getStatus().name(),x.getFornecedor(),x.getValorTotal(),x.getValorPago(),x.getObservacoes(),x.getNumeroPedido());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM pedidos_pecas WHERE numero_pedido=?",id);}public boolean existsById(Long id){return !query("SELECT numero_pedido FROM pedidos_pecas WHERE numero_pedido=?",r->r.getLong(1),id).isEmpty();}private PedidoPecas map(ResultSet r)throws SQLException{OrdemServico os=OrdemServico.builder().comCliente(new Cliente()).comVeiculo(new Veiculo()).comDescricaoProblema("Pedido carregado do banco").comStatus(StatusOrdemServico.ABERTO).build();setId(os,"numeroOS",r.getLong("numero_os"));PedidoPecas x=new PedidoPecas(os,StatusPedidoPecas.valueOf(r.getString("status")));setId(x,"numeroPedido",r.getLong("numero_pedido"));x.setFornecedor(r.getString("fornecedor"));x.setValorTotal(r.getDouble("valor_total"));x.setValorPago(r.getDouble("valor_pago"));x.setObservacoes(r.getString("observacoes"));x.setDataAtualizacao(time(r,"data_atualizacao"));x.setDataEntrega(time(r,"data_entrega"));return x;}}
